    if (mh_state.count == 0) {
        mh_state.minimum = *current_val;
        mh_state.maximum = *current_val;
    } else {
        if (current_val->x < mh_state.minimum.x) mh_state.minimum.x = current_val->x;
        if (current_val->y < mh_state.minimum.y) mh_state.minimum.y = current_val->y;
        if (current_val->z < mh_state.minimum.z) mh_state.minimum.z = current_val->z;

        if (current_val->x > mh_state.maximum.x) mh_state.maximum.x = current_val->x;
        if (current_val->y > mh_state.maximum.y) mh_state.maximum.y = current_val->y;
        if (current_val->z > mh_state.maximum.z) mh_state.maximum.z = current_val->z;
