            mh_state.count = 0;
        } else {
            // Insufficient Excitation
            mh_state.rejected++;
            unint32 max_rej = mh_config.max_rejected_windows;

            if (max_rej == 0) {
                // Unlimited tolerance: Restart collection
                mh_state.count = 0;
                mh_state.minimum.x = 0.0; mh_state.minimum.y = 0.0; mh_state.minimum.z = 0.0;
                mh_state.maximum.x = 0.0; mh_state.maximum.y = 0.0; mh_state.maximum.z = 0.0;
            } else {
                if (mh_state.rejected > max_rej) {
                    // Reached limit and exceeded: Latch FAULT
                    mh_state.mode = MH_FAULT;
                    mh_output.mode = MH_FAULT;
                } else {
                    // Within tolerance: Restart collection
                    mh_state.count = 0;
                    mh_state.minimum.x = 0.0; mh_state.minimum.y = 0.0; mh_state.minimum.z = 0.0;
                    mh_state.maximum.x = 0.0; mh_state.maximum.y = 0.0; mh_state.maximum.z = 0.0;
                }
            }
        }
    } else {
        // Still collecting
        mh_output.mode = mh_state.mode;
    }
} else if (mh_state.mode == MH_READY) {
    // In Ready state, maintain last known good output
    // No action required as outputs are preserved from the transition to READY
}

