switch (mh_state.mode) {
    case MH_IDLE:
        mh_state.mode = MH_COLLECT;
        mh_state.count = 0;
        mh_state.rejected = 0;
        // Will be initialized by first sample in COLLECT case
        break;

    case MH_COLLECT:
        // Initialize min/max with first sample if count is 0
        if (mh_state.count == 0) {
            mh_state.minimum = *sample_val;
            mh_state.maximum = *sample_val;
        } else {
            if (sample_val->x < mh_state.minimum.x) mh_state.minimum.x = sample_val->x;
            if (sample_val->x > mh_state.maximum.x) mh_state.maximum.x = sample_val->x;
            if (sample_val->y < mh_state.minimum.y) mh_state.minimum.y = sample_val->y;
            if (sample_val->y > mh_state.maximum.y) mh_state.maximum.y = sample_val->y;
            if (sample_val->z < mh_state.minimum.z) mh_state.minimum.z = sample_val->z;
            if (sample_val->z > mh_state.maximum.z) mh_state.maximum.z = sample_val->z;
        }

        mh_state.count++;

        if (mh_state.count < mh_config.required) {
            break;
        }

        // Window complete
        adcs_vec3_t current_bias;
        adcs_vec3_t current_half_span;

        current_bias.x = (mh_state.maximum.x + mh_state.minimum.x) * 0.5;
        current_bias.y = (mh_state.maximum.y + mh_state.minimum.y) * 0.5;
        current_bias.z = (mh_state.maximum.z + mh_state.minimum.z) * 0.5;

        current_half_span.x = (mh_state.maximum.x - mh_state.minimum.x) * 0.5;
        current_half_span.y = (mh_state.maximum.y - mh_state.minimum.y) * 0.5;
        current_half_span.z = (mh_state.maximum.z - mh_state.minimum.z) * 0.5;

        int all_ready = 1;
        if (current_half_span.x < mh_config.minimum_span) all_ready = 0;
        if (current_half_span.y < mh_config.minimum_span) all_ready = 0;
        if (current_half_span.z < mh_config.minimum_span) all_ready = 0;

        if (all_ready) {
            mh_state.mode = MH_READY;
            mh_output.mode = MH_READY;
            mh_output.bias = current_bias;
            mh_output.half_span = current_half_span;
            mh_output.span_norm = adcs_vec3_norm(&current_half_span);
            mh_output.span_energy = adcs_vec3_dot(&current_half_span, &current_half_span);
        } else {
            mh_state.rejected++;
            if (mh_config.max_rejected_windows != 0 && mh_state.rejected > mh_config.max_rejected_windows) {
                mh_state.mode = MH_FAULT;
                mh_output.mode = MH_FAULT;
            } else {
                mh_state.count = 0;
                // min/max will be re-initialized by next sample due to count==0 check
            }
        }
        break;

    case MH_READY:
    case MH_FAULT:
        // No action on new samples
        break;
}

